// La anti-repetición general (misma alerta en 10 min) la hace Enviar_Alerta.
// n8n devuelve un ítem vacío cuando la consulta no trae filas: se filtra por una columna clave.
// D2: crecimiento > 20 % en 30 min. El SQL ya guardó la foto y reinició la ventana de la tabla alertada.
const filas = $input.all().map(i => i.json).filter(r => r.tabla);
return filas.map(r => ({ json: {
  codigo: 'D2',
  severidad: 'ADVERTENCIA',
  tipo: 'Crecimiento anormal de datos (> 20 % en 30 min)',
  tabla: r.tabla,
  detalle: `Filas: ${r.antes} → ${r.ahora} (+${r.crecimiento_pct} %, umbral: 20 %) desde ${r.desde}`,
  query: `SELECT count(*) FROM ${r.tabla}; -- comparado con snapshot_tablas`,
  usuario: 'N/A (revisar auditoria_datos o pg_stat_statements)',
  accion: 'Confirmar si la carga es legítima. Si no, identificar al usuario en auditoria_datos y depurar los registros.'
}}));
